{id:'MAC-03',kind:'reference',category:'mac',title:'Mac launcher and trainer',platforms:['macOS'],symptoms:['Where is the launcher on Mac?','How do I open the trainer on Mac?'],log_signatures:[],cause:'Since 28 Oct the Mac app includes the launcher and trainer.',player_fix:['Trainer: Cmd+T or F4. A controller View button also opens it from the pause menu.','GTA Online is opened from the launcher GTA Online page.'],status:'feature',released:true,still_open:false,fixed_in:'Batch 98, 28 Oct release',related:['ONLINE-01']},
{id:'THIRD-01',kind:'issue',category:'third-party',title:'MetalShade / posthook installed',platforms:['iOS','iPadOS'],symptoms:['MetalShade button in trainer','SHRINK MOD button in launcher','Crash with MetalShade','Is MetalShade safe?'],log_signatures:['d3dr1.dylib','libposthook.dylib','metalshade.log','[proxy]'],cause:'MetalShade is a player-made third-party add-on, not part of the port. Each port update replaces its patched files. The developer reviewed its source on 31 Oct and did not find network, contacts, photos or keychain use, but the port does not support it.',player_fix:['For a crash, first reinstall the plain public release IPA over the current app so data and saves stay, then reproduce the problem again.','Questions specific to MetalShade go to its author.'],status:'third-party',released:null,still_open:false,fixed_in:null,related:[]}
