const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
const tok=v=>[...new Set(norm(v).split(' ').filter(x=>x.length>2))];
function score(e,q){const n=norm(q),qt=tok(q),text=norm([e.title,...e.symptoms,...e.log_signatures,e.cause,...e.player_fix].join(' '));let s=0,h=0,sig=false;for(const raw of e.log_signatures){const x=norm(raw);if(x&&n.includes(x)){s+=85;sig=true}else{const a=tok(raw);const m=a.filter(t=>n.includes(t)).length;if(a.length&&m>=Math.min(2,a.length)){s+=45+m*5;sig=true}}}for(const t of qt)if(text.includes(t)){s+=3;h++}for(const symptom of e.symptoms){const x=norm(symptom);if(x.length>8&&(n.includes(x)||x.includes(n)&&n.length>12))s+=22}return{s,h,sig}}
function render(e,sig){const parts=[e.title,`Developer KB · ${e.id} · 31 Oct 2026`,sig?'The text matches a recorded signature from the developer KB.':'This matches a current developer-KB symptom.',`Status: ${e.status}${e.released===false?' (documented for a next update, not the 30 Oct public release)':''}.`,e.cause,'What to do:\n'+e.player_fix.map((x,i)=>`${i+1}. ${x}`).join('\n'),e.fixed_in?`Build / fix scope: ${e.fixed_in}`:'',e.related.length?`Related: ${e.related.join(', ')}`:''].filter(Boolean);return{text:parts.join('\n\n'),topic:e.kind==='reference'?'developer-reference':'developer-troubleshooting',grounded:true,knowledgeId:e.id,discord:!!e.still_open}}
function answer(raw){const q=String(raw||'').trim();if(!q)return null;const ranked=E.map(e=>({e,...score(e,q)})).sort((a,b)=>b.s-a.s);const b=ranked[0],n=ranked[1];if(!b)return null;if(b.sig||b.s>=18&&b.h>=2&&b.s-(n?.s||0)>=2)return render(b.e,b.sig);return null}
function install(){const kb=window.FranklinDeveloperKB;if(!kb||kb.__developerOverlay20261031)return false;const original=kb.answer?.bind(kb);kb.answer=async raw=>answer(raw)||(original?await original(raw):null);const oldStatus=kb.status?.bind(kb);kb.status=()=>({...oldStatus?.(),developerOverlay:'2026-10-31',overlayEntries:E.length});kb.__developerOverlay20261031=true;return true}
